'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {hotelRpc,usd} from '@/lib/pilot';
import {readBillingCheckoutReview} from '@/lib/billing-checkout-review';
import {BillingCheckoutConfirm} from '@/components/billing-checkout-confirm';
type Props={onReviewFolio?:()=>void;settledOnly?:boolean;onBusyChange?:(busy:boolean)=>void;onSaved?:()=>void;actor:string;tenant:string;property:string;reservation:string};
export function BillingCheckoutReview(props:Props){return <Review key={[props.actor,props.tenant,props.property,props.reservation].join('/')} {...props}/>}
function Review({onReviewFolio,settledOnly=false,actor,tenant,property,reservation,onSaved,onBusyChange}:Props){
 const [review,setReview]=useState<ReturnType<typeof readBillingCheckoutReview>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const [snapshot,setSnapshot]=useState<unknown>(null);
 const [saving,setSaving]=useState(false);
 const savingChanged=useCallback((value:boolean)=>{setSaving(value);onBusyChange?.(value)},[onBusyChange]);
 const sequence=useRef(0),alive=useRef(false),readTimer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);
 async function load(){if(saving)return;const current=++sequence.current;setBusy(true);setReview(null);setSnapshot(null);setError('');let timer:ReturnType<typeof setTimeout>|undefined;try{const data=await Promise.race([hotelRpc<unknown>('billing_checkout_review',{p_tenant:tenant,p_property:property,p_reservation:reservation}),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Error('Loading the checkout review took too long. Check your connection and refresh the review.')),15000);readTimer.current=timer})]);const result=readBillingCheckoutReview(data,{tenant,property,reservation});if(alive.current&&current===sequence.current){setReview(result);setSnapshot(data)}}catch(e){if(alive.current&&current===sequence.current)setError(e instanceof Error?e.message:'Unable to review checkout.')}finally{clearTimeout(timer);if(readTimer.current===timer)readTimer.current=undefined;if(alive.current&&current===sequence.current)setBusy(false)}}
 useEffect(()=>{alive.current=true;void load();return()=>{alive.current=false;sequence.current++;clearTimeout(readTimer.current)}},[tenant,property,reservation]);
 return <section aria-label="Checkout balance review"><h3>Checkout balance review</h3><button className="secondary" disabled={busy||saving} onClick={()=>void load()}>{busy?'Loading checkout review…':'Refresh checkout review'}</button>{error&&<p role="alert" className="pilot-error">{error}</p>}{review&&<><p>{review.status} · Property date {review.businessDate}</p>{!review.eligible&&<p>This stay is not eligible for checkout on this date.</p>}{review.balance.available?<div className="detail-grid"><div>Original balance<b>{usd(Number(review.balance.originalMinor))}</b></div><div>Transferred charges<b>{usd(Number(review.balance.transferredMinor))}</b></div><div>{review.disposition==='credit'?'Guest credit':'Guest balance'}<b>{usd(Math.abs(Number(review.balance.guestMinor)))}</b></div></div>:<p>Guest charges are unavailable. Reconcile the folio before proceeding.</p>}<p>{review.disposition==='zero'?'No remaining guest balance.':review.disposition==='outstanding'?'Review payment or an approved outstanding-balance arrangement before checkout.':review.disposition==='credit'?'Review this credit before checkout. A credit does not authorize an automatic refund.':'No payment amount can be suggested.'}</p></>}{onReviewFolio&&<button type="button" className="secondary" disabled={busy||saving} onClick={onReviewFolio}>Open folio / review payment</button>}{onSaved?<BillingCheckoutConfirm settledOnly={settledOnly} actor={actor} tenant={tenant} property={property} reservation={reservation} review={snapshot} onSaved={onSaved} onBusyChange={savingChanged}/>:<p className="muted">Review only. This does not check out the guest or collect a payment.</p>}</section>
}
